class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        if bias:
            raise ValueError("Bias not supported in PTX kernel")
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.kernel_size = kernel_size

        # weight tensor in fp16: (out_channels, in_channels // groups, K, K, K)
        self.weight = nn.Parameter(
            torch.empty(out_channels,
                        in_channels // groups,
                        kernel_size,
                        kernel_size,
                        kernel_size,
                        dtype=torch.float16,
                        device='cuda')
        )
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        # load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C_in, D_in, H_in, W_in = x.shape
        K = self.kernel_size
        stride = self.stride
        pad = self.padding
        dil = self.dilation
        groups = self.groups
        C_out = self.weight.shape[0]

        D_out = (D_in + 2 * pad - dil * (K - 1) - 1) // stride + 1
        H_out = (H_in + 2 * pad - dil * (K - 1) - 1) // stride + 1
        W_out = (W_in + 2 * pad - dil * (K - 1) - 1) // stride + 1

        out = torch.empty(N, C_out, D_out, H_out, W_out,
                         dtype=torch.float16, device='cuda')

        total = N * C_out * D_out * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block

        ptx_launch(self.module,
                   "conv3d_fp16",
                   (grid_x, 1, 1),
                   (block, 1, 1),
                   [
                       x.data_ptr(),
                       self.weight.data_ptr(),
                       out.data_ptr(),
                       N,
                       C_in,
                       D_in,
                       H_in,
                       W_in,
                       C_out,
                       D_out,
                       H_out,
                       W_out,
                       K,
                       stride,
                       pad,
                       dil,
                       groups
                   ])
        return out
