    mul.lo.s32      %r61, %r60, %r10;         // * K
    add.s32         %r62, %r61, %r39;         // + kh
    mul.lo.s32      %r63, %r62, %r10;         // * K
    add.s32         %r64, %r63, %r44;         // + kw

    mul.wide.s32    %rd11, %r64, 2;           // byte offset
    cvta.to.global.u64 %rd12, %rd2;          // base weight pointer
    add.s64         %rd13, %rd12, %rd11;
    ld.global.f16   %h1, [%rd13];

    // -------------------------------------------------
    // Multiply‑accumulate in fp32
    // -------------------------------------------------
    cvt.f32.f16     %f1, %h0;
    cvt.f32.f16     %f2, %h1;
    fma.rn.f32      %f0, %f2, %f1, %f0;      // f0 += f2 * f1

    // -------------------------------------------------
    // Increment kw loop
    // -------------------------------------------------
$KW_INC:
    add.u32         %r44, %r44, 1;
    bra $KW_LOOP;

    // -------------------------------------------------
    // Increment kh loop
    // -------------------------------------------------
$KH_INC:
    add.u32         %r39, %r39, 1;
    bra $KH_LOOP;

    // -------------------------------------------------
    // Increment kd loop
    // -------------------------------------------------
$KD_INC:
    add.u32         %r34, %r34, 1;
    bra $KD_LOOP;

    // -------------------------------------------------
    // Increment ic loop
    // -------------------------------------------------
$IC_INC:
    add.u32         %r32, %r32, 1;
    bra $IC_LOOP;

    // -------------------------------------------------
    // Write output (fp16)
    // -------------------------------------------------
$KERNEL_END:
    // convert accumulator to fp16
    cvt.rn.f16.f32  %h2, %f0;

    // output linear index = (((((n * C_out) + oc) * D_out + d_out) * H_out + h_out) * W_out + w_out)
    mul.lo.s32      %r65, %r29, %r6;          // n*C_out
    add.s32         %r66, %r65, %r28;         // + oc
    mul.lo.s32      %r67, %r66, %r7;          // * D_out
    add.s32         %r68, %r67, %r26;         // + d_out
    mul.lo.s32      %r69, %r68, %r8;          // * H_out
    add.s32         %r70, %r69, %r24;         // + h_out
    mul.lo.s32      %r71, %r70, %r9;          // * W_out
    add.s32         %r72, %r71, %r22;         // + w_out

    mul.wide.s32    %rd14, %r72, 2;           // byte offset
    cvta.to.global.u64 %rd15, %rd3;          // base output pointer
    add.s64         %rd16, %rd15, %rd14;
    st.global.f16   [%rd16], %h2;

$L_EXIT:
    ret;
